      protected function telefonoContacto(): Attribute
      {
          return Attribute::make(
              get: function () {
                  if (!blank($this->celular)) {
                      return $this->celular;
                  }
                  if (!blank($this->telefono_tutor)) {
                      return $this->telefono_tutor;
                  }
                  return null;
              }
          );
      }
